        for (int i = key.length() - 1; i >= 0; i--) {
            TrieNode child = pathNodes[i].child(pathIdxs[i]);
            if (child.hasChildren() || child.isEndOfWord) break;
            pathNodes[i].removeChild(pathIdxs[i]);
        }

        return true;
